// ObserveCleanupIfVersion records one owner's current cleanup observation.
// Only a deleted row at the exact observed revision can accept the write.
// A completion does not stop recovery or prevent late external effects.
func (s *Store) ObserveCleanupIfVersion(ctx context.Context, entity, id string, version int64, owner string, complete bool) error {
	if ctx == nil || s == nil || s.db == nil || id == "" || version < 1 {
		return errors.New("cleanup observation requires a context, store, identity, and revision")
	}

	operation, cancel := context.WithTimeout(ctx, transactionTimeout)
	defer cancel()

	switch entity {
	case "ManagedDatabase":
		switch owner {
		case "provider":
		default:
			return errors.New("cleanup owner is not declared")
		}

		result := s.db.WithContext(operation).Exec("UPDATE \"managed_databases\" SET stego_cleanup=jsonb_set(stego_cleanup,ARRAY[?]::text[],to_jsonb(?::boolean)),updated_time=now() WHERE id=? AND id COLLATE \"C\"=? AND stego_revision=? AND deleted_at IS NOT NULL", owner, complete, id, id, version)
		if result.Error != nil {
			return result.Error
		}
		if result.RowsAffected != 1 {
			return ErrVersionConflict
		}
		return nil
	case "Gateway":
		switch owner {
		case "identity", "workload":
		default:
			return errors.New("cleanup owner is not declared")
		}
		if owner == "workload" {
			return errors.New("cleanup owner requires a target observation")
		}

		result := s.db.WithContext(operation).Exec("UPDATE \"gateways\" SET stego_cleanup=jsonb_set(stego_cleanup,ARRAY[?]::text[],to_jsonb(?::boolean)),updated_time=now() WHERE id=? AND id COLLATE \"C\"=? AND stego_revision=? AND deleted_at IS NOT NULL", owner, complete, id, id, version)
		if result.Error != nil {
			return result.Error
		}
		if result.RowsAffected != 1 {
			return ErrVersionConflict
		}
		return nil
	default:
		return errors.New("entity does not declare cleanup owners")
	}
}

// CleanupObservations returns the recorded state for every declared owner.
// A live resource has no completed cleanup. Callers must also check deletion.
func (row ManagedDatabase) CleanupObservations() (map[string]bool, error) {
	var raw map[string]json.RawMessage
	if json.Unmarshal(row.CleanupState, &raw) != nil || len(raw) != 1 {
		return nil, errors.New("invalid cleanup state")
	}
	states := make(map[string]bool, 1)
	for _, owner := range []string{"provider"} {
		value, ok := raw[owner]
		if !ok || (string(value) != "true" && string(value) != "false") {
			return nil, errors.New("invalid cleanup observation")
		}
		states[owner] = string(value) == "true"
	}

	return states, nil
}
func (row ManagedDatabase) CleanupComplete(owner string) bool {
	if !row.DeletedAt.Valid {
		return false
	}
	states, err := row.CleanupObservations()
	return err == nil && states[owner]
}
func (row ManagedDatabase) PendingCleanup() ([]string, error) {
	states, err := row.CleanupObservations()
	if err != nil {
		return nil, err
	}
	var pending []string
	if !row.DeletedAt.Valid {
		return pending, nil
	}
	for _, owner := range []string{"provider"} {
		if !states[owner] {
			pending = append(pending, owner)
		}
	}
	return pending, nil
}

// CleanupObservations returns the recorded state for every declared owner.
// A live resource has no completed cleanup. Callers must also check deletion.
func (row Gateway) CleanupObservations() (map[string]bool, error) {
	var raw map[string]json.RawMessage
	if json.Unmarshal(row.CleanupState, &raw) != nil || len(raw) != 2 {
		return nil, errors.New("invalid cleanup state")
	}
	states := make(map[string]bool, 2)
	for _, owner := range []string{"identity", "workload"} {
		value, ok := raw[owner]
		if !ok || (string(value) != "true" && string(value) != "false") {
			return nil, errors.New("invalid cleanup observation")
		}
		states[owner] = string(value) == "true"
	}

	targets, err := row.CleanupTargets()
	if err != nil {
		return nil, err
	}
	for owner, entries := range targets {
		complete := row.DeletedAt.Valid
		for _, observed := range entries {
			complete = complete && observed
		}
		if states[owner] != complete {
			return nil, errors.New("cleanup owner does not match its target observations")
		}
	}

	return states, nil
}
func (row Gateway) CleanupComplete(owner string) bool {
	if !row.DeletedAt.Valid {
		return false
	}
	states, err := row.CleanupObservations()
	return err == nil && states[owner]
}
func (row Gateway) PendingCleanup() ([]string, error) {
	states, err := row.CleanupObservations()
	if err != nil {
		return nil, err
	}
	var pending []string
	if !row.DeletedAt.Valid {
		return pending, nil
	}
	for _, owner := range []string{"identity", "workload"} {
		if !states[owner] {
			pending = append(pending, owner)
		}
	}
	return pending, nil
}

// ReplaceIfVersion rejects absent, deleted, or changed rows. Use the revision
// read before external work. A new transaction does not make an old observation
// current. Access checks, field ownership, and events belong in the transaction.
// The callback must return errors so a failed write cannot commit its events.
func (s *Store) ReplaceIfVersion(ctx context.Context, entity, id string, version int64, value any) error {
	if ctx == nil || s == nil || s.db == nil {
		return errors.New("conditional write requires a context and store")
	}
	if id == "" || version < 1 {
		return errors.New("conditional write requires an identity and positive version")
	}
	operation, cancel := context.WithTimeout(ctx, transactionTimeout)
	defer cancel()
	switch entity {
	case "ManagedDatabase":

		data, err := json.Marshal(value)
		if err != nil {
			return err
		}
		var row ManagedDatabase
		if err := json.Unmarshal(data, &row); err != nil {
			return err
		}
		row.ID = id
		result := s.db.WithContext(operation).Model(&ManagedDatabase{}).Where("id = ? AND id COLLATE \"C\" = ? AND stego_revision = ?", id, id, version).Select([]string{"name", "provider", "namespace", "region", "engine", "engine_version", "instance_class", "connection_secret", "status"}).Updates(&row)
		if result.Error != nil {
			if isUniqueConstraintError(result.Error) {
				return versioncontract.ErrConflict
			}
			return result.Error
		}
		if result.RowsAffected != 1 {
			return ErrVersionConflict
		}
		return nil

	case "Gateway":

		data, err := json.Marshal(value)
		if err != nil {
			return err
		}
		var row Gateway
		if err := json.Unmarshal(data, &row); err != nil {
			return err
		}
		row.ID = id
		result := s.db.WithContext(operation).Model(&Gateway{}).Where("id = ? AND id COLLATE \"C\" = ? AND stego_revision = ?", id, id, version).Select([]string{"name", "cluster_id", "release_id", "database_id", "namespace", "external_dns", "tls_mode", "service_type", "image", "supervisor_image", "server_dns_names", "route_address", "console_address", "oidc", "route", "credential_driver", "active_sandbox_count"}).Updates(&row)
		if result.Error != nil {
			if isUniqueConstraintError(result.Error) {
				return versioncontract.ErrConflict
			}
			return result.Error
		}
		if result.RowsAffected != 1 {
			return ErrVersionConflict
		}
		return nil

	default:
		return errors.New("conditional write requires a versioned entity")
	}
}

// ObserveIfVersion writes a complete observation group and records its current
// desired generation. It does not grant access to that group. Authorize the
// caller and insert events in the same transaction. Repeat external work after
// a conflict; never give an old observation a newer revision.
func (s *Store) ObserveIfVersion(ctx context.Context, entity, id string, version int64, group string, values map[string]any) error {
	if ctx == nil || s == nil || s.db == nil || id == "" || version < 1 {
		return errors.New("observation requires a context, store, identity, and positive revision")
	}

	var statement string
	var fields []string
	var decode func([]byte) ([]any, error)
	switch entity {
	case "Gateway":
		switch group {
		case "workload":
			statement = "UPDATE \"gateways\" SET \"phase\" = ?, \"status\" = ?, stego_observations=jsonb_set(stego_observations, ARRAY[?]::text[], to_jsonb(stego_generation)), updated_time=now() WHERE id=? AND id COLLATE \"C\"=? AND stego_revision=? AND deleted_at IS NULL"
			fields = []string{"phase", "status"}
			decode = func(data []byte) ([]any, error) {
				var row Gateway
				if err := json.Unmarshal(data, &row); err != nil {
					return nil, err
				}
				return []any{row.Phase, row.Status}, nil
			}
		default:
			return errors.New("unknown observation group")
		}
	default:
		return errors.New("entity has no observation groups")
	}
	if len(values) != len(fields) {
		return errors.New("observation must contain exactly its declared fields")
	}
	for _, field := range fields {
		if _, ok := values[field]; !ok {
			return errors.New("observation must contain exactly its declared fields")
		}
	}
	data, err := json.Marshal(values)
	if err != nil {
		return err
	}
	if len(data) > 1<<20 {
		return errors.New("observation exceeds its byte limit")
	}
	operation, cancel := context.WithTimeout(ctx, transactionTimeout)
	defer cancel()
	args, err := decode(data)
	if err != nil {
		return err
	}
	args = append(args, group, id, id, version)
	result := s.db.WithContext(operation).Exec(statement, args...)
	if result.Error != nil {
		if isUniqueConstraintError(result.Error) {
			return versioncontract.ErrConflict
		}
		return result.Error
	}
	if result.RowsAffected != 1 {
		return ErrVersionConflict
	}
	return nil

}

// ObservedGeneration returns zero for an absent, invalid, or unknown group.
func (row Gateway) ObservedGeneration(group string) int64 {
	switch group {
	case "workload":
	default:
		return 0
	}
	var observed map[string]json.RawMessage
	if json.Unmarshal(row.ObservedGenerations, &observed) != nil {
		return 0
	}
	var value int64
	if json.Unmarshal(observed[group], &value) != nil {
		return 0
	}
	if value < 1 || value > row.ResourceGeneration {
		return 0
	}
	return value
}

// CurrentObservations replaces unconfirmed group fields with their declared
// unobserved value or nil. Stored observations remain available for diagnosis.
func (row Gateway) CurrentObservations() Gateway {
	if row.ResourceGeneration < 1 || row.ObservedGeneration("workload") != row.ResourceGeneration {
		{
			value := "Provisioning"
			row.Phase = &value
		}
		{
			value := "ObservationPending"
			row.Status = &value
		}
	}
	return row
}

// ObserveTargetCleanupIfVersion records one target without removing its history.
func (s *Store) ObserveTargetCleanupIfVersion(ctx context.Context, entity, id string, version int64, owner, target string, complete bool) error {
	if ctx == nil || s == nil || s.db == nil || id == "" || version < 1 {
		return errors.New("target cleanup requires a context, store, identity, and revision")
	}

	if len(target) < 1 || len(target) > 256 || !utf8.ValidString(target) || strings.ContainsRune(target, 0) {
		return errors.New("invalid cleanup target")
	}
	operation, cancel := context.WithTimeout(ctx, transactionTimeout)
	defer cancel()
	switch entity {
	case "Gateway":
		switch owner {
		case "workload":
		default:
			return errors.New("target cleanup owner is not declared")
		}
		result := s.db.WithContext(operation).Exec("UPDATE \"gateways\" SET stego_cleanup_targets=jsonb_set(stego_cleanup_targets,ARRAY[?,?]::text[],to_jsonb(?::boolean),false),updated_time=now() WHERE id=? AND id COLLATE \"C\"=? AND stego_revision=? AND deleted_at IS NOT NULL AND jsonb_exists(stego_cleanup_targets->?,?)", owner, target, complete, id, id, version, owner, target)
		if result.Error != nil {
			return fmt.Errorf("record target cleanup: %w", result.Error)
		}
		if result.RowsAffected != 1 {
			return ErrVersionConflict
		}
		return nil
	default:
		return errors.New("entity does not declare cleanup targets")
	}

}

// CleanupTargets returns the retained observations, including earlier targets.
func (row Gateway) CleanupTargets() (map[string]map[string]bool, error) {
	if len(row.CleanupTargetState) > 65536 {
		return nil, errors.New("cleanup target history exceeds its limit")
	}
	var raw map[string]map[string]json.RawMessage
	if json.Unmarshal(row.CleanupTargetState, &raw) != nil || len(raw) != 1 {
		return nil, errors.New("invalid cleanup target history")
	}
	result := make(map[string]map[string]bool, len(raw))
	total := 0
	{
		entries, ok := raw["workload"]
		if !ok || len(entries) == 0 {
			return nil, errors.New("missing cleanup target history")
		}
		if _, ok := entries[row.ClusterID]; !ok {
			return nil, errors.New("current cleanup target is absent")
		}
		states := make(map[string]bool, len(entries))
		for target, value := range entries {
			if len(target) < 1 || len(target) > 256 || !utf8.ValidString(target) || strings.ContainsRune(target, 0) || (string(value) != "true" && string(value) != "false") {
				return nil, errors.New("invalid cleanup target observation")
			}
			states[target] = string(value) == "true"
			total++
		}
		result["workload"] = states
	}
	if total > 128 {
		return nil, errors.New("cleanup target history exceeds its limit")
	}
	return result, nil
}
